mapper.select:
/* 리스트 조회 동적쿼리 */
    SELECT
        s.id,
        s.name,
        s.theme,
        s.region_id,
        COALESCE(s.bookmark_count, 0) AS bookmark_count,
        COALESCE(s.like_count, 0) AS like_count,


                ROUND(CAST(
                    ST_Distance(
                        s.location::geography,
                        ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography
                    ) / 1000.0 AS numeric
                ), 2)


                NULL::numeric


            AS distance_km
    FROM spots s

        (
            s.status = #{status}


                OR s.user_id = #{userId}

        )
        AND (
            s.rel_yn = #{relYn}


                OR s.user_id = #{userId}

        )
        AND s.deleted_at IS NULL
        AND (
            s.region_id IN

                #{regionId}



                OR s.user_id = #{userId}

        )

            AND s.theme IN

                #{themeCode}



    ORDER BY
    /* 1순위: 조회조건 지역 매칭 여부(다른 지역인 내 스팟은 뒤로), 2순위: 내 스팟 여부(내 스팟은 뒤로 -
       추천/거리순 노출을 방해하지 않도록), 3순위: 기존 정렬 기준. region_id 원값(ASC)으로 1순위를 대신하면
       조회조건 밖의 다른 지역 내 스팟이 region_id 숫자값에 따라 임의의 위치에 끼어든다 */
    CASE WHEN s.region_id IN

        #{regionId}

        THEN 0 ELSE 1 END,

        CASE WHEN s.user_id = #{userId} THEN 1 ELSE 0 END,



            ST_Distance(
                s.location::geography,
                ST_SetSRID(ST_MakePoint(#{lng}, #{lat}), 4326)::geography
            )


            /* 추천순 = 좋아요 많은 순. 동률은 북마크 수, 그다음 최신 등록 순으로 가른다 */
            s.like_count DESC, s.bookmark_count DESC, s.id DESC


    LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM spots s

    (
        s.status = #{status}


            OR s.user_id = #{userId}

    )
    AND (
        s.rel_yn = #{relYn}


            OR s.user_id = #{userId}

    )
    AND s.deleted_at IS NULL
    AND (
        s.region_id IN

            #{regionId}



            OR s.user_id = #{userId}

    )

        AND s.theme IN

            #{themeCode}

/* 뷰포트 조회 동적쿼리 */
    SELECT s.id, s.latitude, s.longitude, s.user_id, s.region_id
    FROM spots s
    WHERE s.location && ST_MakeEnvelope(#{minLng}, #{minLat}, #{maxLng}, #{maxLat}, 4326)
        AND (
            s.status = #{status}


                OR s.user_id = #{userId}

        )
        AND (
            s.rel_yn = #{relYn}


                OR s.user_id = #{userId}

        )
        AND s.deleted_at IS NULL
        AND (
            s.region_id IN

                #{regionId}



                OR s.user_id = #{userId}

        )

            AND s.theme IN

                #{themeCode}
